 的 clips/selfQaNote/creativeReview/sourceFidelityAudit 信封、图片 prompt 与 negativePrompt 不得进入视频模型正文；prompt_only 不产生媒体副作用。","workflowDeliveryArtifactType":"tapcanvas.prompt-package/v2","workflowPermission":{"visibilityRoles":["admin"],"editRoles":["admin"],"runRoles":["admin"]},"adminWorkflow":true,"kind":"workflowStage","status":"idle","nodeWidth":56,"nodeHeight":56}},{"id":"builtin-video-production-v90:voice-materialize","type":"taskNode","parentId":"builtin-video-production-v90:group","position":{"x":176,"y":528},"data":{"label":"原生音频合同","workflowKey":"one-click-production/v1","workflowDefinitionVersion":1,"workflowCanvasDefinitionVersion":90,"workflowCanvasDefinitionFingerprint":"sha256:c2bfa1aa9ec6d701d5ba77a9ed330569e7b409b0a955bdd74c028b644e4fd8bd","workflowInstanceId":"builtin-video-production-v90","workflowExecutionScope":"media_delivery","workflowExecutionVariant":"full_video","workflowNodeId":"voice-materialize","workflowNodeKind":"voice_manifest_empty","workflowAtomicSpec":{"version":1,"category":"control","operation":"voice_manifest_empty","executorRef":"video.voice-manifest.empty/v1","executionMode":"once","inputPorts":["trigger"],"outputPorts":["voice-manifest"]},"workflowInputPorts":["trigger"],"workflowOptionalInputPorts":[],"workflowOutputPorts":["voice-manifest"],"workflowOperationDescription":"供应商原生对白音频不使用参考音频，确定性输出空 VoiceManifest。","workflowOutputArtifactType":"tapcanvas.voice-manifest/v1","workflowPermission":{"visibilityRoles":["admin"],"editRoles":["admin"],"runRoles":["admin"]},"adminWorkflow":true,"kind":"workflowStage","status":"idle","nodeWidth":56,"nodeHeight":56}},{"id":"builtin-video-production-v90:cost-estimate","type":"taskNode","parentId":"builtin-video-production-v90:group","position":{"x":312,"y":528},"data":{"label":"费用预估","workflowKey":"one-click-production/v1","workflowDefinitionVersion":1,"workflowCanvasDefinitionVersion":90,"workflowCanvasDefinitionFingerprint":"sha256:c2bfa1aa9ec6d701d5ba77a9ed330569e7b409b0a955bdd74c028b644e4fd8