ract 的完整 clips 信封；创作语义由 tapcanvas-video-prompt-writer 在提交前自行验收，宿主不以第二套提示词或返回纠偏覆盖。","workflowAgentDefinitionId":"video-prompt-writer","workflowPromptExampleMediaType":"video","workflowAgentMaxOutputTokens":65536,"workflowRequiredSkills":["tapcanvas-video-prompt-writer","tapcanvas-dialogue-drama"],"workflowSkillId":"tapcanvas-video-prompt-writer","workflowAgentOutputArtifactType":"tapcanvas.clip-prompts/v2","workflowOutputArtifactType":"tapcanvas.clip-prompts/v2","workflowPermission":{"visibilityRoles":["admin"],"editRoles":["admin"],"runRoles":["admin"]},"adminWorkflow":true,"kind":"workflowStage","status":"idle","nodeWidth":56,"nodeHeight":56}},{"id":"builtin-video-production-v90:prompt-package","type":"taskNode","parentId":"builtin-video-production-v90:group","position":{"x":40,"y":528},"data":{"label":"提示词包汇总","workflowKey":"one-click-production/v1","workflowDefinitionVersion":1,"workflowCanvasDefinitionVersion":90,"workflowCanvasDefinitionFingerprint":"sha256:c2bfa1aa9ec6d701d5ba77a9ed330569e7b409b0a955bdd74c028b644e4fd8bd","workflowInstanceId":"builtin-video-production-v90","workflowExecutionScope":"media_delivery","workflowExecutionVariant":"full_video","workflowNodeId":"prompt-package","workflowNodeKind":"prompt_package","workflowAtomicSpec":{"version":1,"category":"delivery","operation":"prompt_package","executorRef":"video.prompt-package.persist/v1","executionMode":"collect","inputPorts":["clip-prompts","clip-contexts","asset-items"],"outputPorts":["prompt-package"]},"workflowInputPorts":["clip-prompts","clip-contexts","asset-items"],"workflowOptionalInputPorts":[],"workflowOutputPorts":["prompt-package"],"workflowOperationDescription":"持久化逐镜提示词与来源追溯。","workflowOutputArtifactType":"tapcanvas.prompt-package/v2","workflowDeliveryRequirement":"持久化完整逐 Clip 提示词包；每个动态 Clip 都有稳定 itemId、原始顺序、来源谱系、合法语义时长、冻结参与者、逐字退出态、完整对白守恒、精确说话人绑定、资产角色结构和 embedded_authoring 复盘证据，以及由唯一 renderer 生成的非空纯执行提示词。provider prompt 只包含自然视听语言、真实 @图N 参考令牌、对白、镜头时间/动作/摄影/光线/材质/声音与结束状态；不得包含 AUDIO/ENTRY+REFERENCES/SHOTS/EXIT、VISUAL_ONLY/SFX_ONLY、SpeechEvent/SpokenText/VoiceManifest、canonical 映射或节点说明。writer 的 clips/selfQaNote/creativeReview/sourceFidelityAudit 信封、图片 prompt 与 negativePrompt 不得进入视频模型正文；prompt_only 不产生媒体副作用。","workflowDeliveryArtifactType":"tapcanvas.prompt-package/v2","workflowPermission":{"visibilityRoles":["admin"],"editRoles":["admin"],"runRoles":["admin"]},"adminWorkflow":true,"kind":"workflowStage","status":"idle","nodeWidth":56,"nodeHeight":56}},{"id":"builtin-video-production-v90:voice-materialize","type":"taskNode","parentId":"builtin-video-production-v90:group","position":{"x":176,"y":528},"data":{"label":"原生音频合同","workflowKey":"one-click-production/v1","workflowDefinitionVersion":1,"workflowCanvasDefinitionVersion":90,"workflowCanvasDefinitionFingerprint":"sha256:c2bfa1aa9ec6d701d5ba77a9ed330569e7b409b0a955bdd74c028b644e4fd8bd","workflowInstanceId":"builtin-video-production-v90","workflowExecutionScope":"media_delivery","workflowExecutionVariant":"full_video","workflowNodeId":"voice-materialize","workflowNodeKind":"voice_manifest_empty","workflowAtomicSpec":{"version":1,"category":"control","operation":"voice_manifest_empty","executorRef":"video.voice-manifest.empty/v1","executionMode":"once","inputPorts":["trigger"],"outputPorts":["voice-manifest"]},"workflowInputPorts":["trigger"],"workflowOptionalInputPorts":[],"workflowOutputPorts":["voice-manifest"],"workflowOperationDescription":"供应商原生对白音频不使用参考音频，确定性输出空 VoiceManifest。","workflowOutputArtifactType":"tapcanvas.voice-manifest/v1","workflowPermission":{"visibilityRoles":["admin"],"editRoles":["admin"],"runRoles":["admin"]},"adminWorkflow":true,"kind":"workflowStage","status":"idle","nodeWidth":56,"nodeHeight":56}},{"id":"builtin-video-production-v90:cost-estimate","type":"taskNode","parentId":"builtin-video-production-v90:group","position":{"x":312,"y":528},"data":{"label":"费用预估","workflowKey":"one-click-production/v1","workflowDefinitionVersion":1,"workflowCanvasDefinitionVersion":90,